    // 在 stdarg.h 里定义。
    va_list ap; // ap: 参数列表(此时未初始化)
    va_start(ap, num); // 初始化参数列表, 从 num 开始
    uint64_t a[MAX_ARGS];
    int i, ret;
    for (i = 0; i 
这一章的核心链路可以概括成三层。第一层是用户态封装，它把 fork、wait、exec、exit、yield、kill、getpid、putc 等接口统一转换成系统调用请求。第二层是异常入口，它识别当前异常是否来自用户态系统调用，如果是，就调整返回地址并进入系统调用分发。第三层是内核语义层，它把系统调用号映射成对应的内核处理函数，例如进程创建、进程退出、等待子进程、程序替换、输出字符以及查看页表等。
理解这部分时，最重要的是分清“参数传递”和“语义执行”这两件事。用户态只负责把请求送进内核，真正的权限检查、地址空间检查、进程状态变化和资源更新都在内核中完成。系统调用返回时，内核会把结果写回到 trapframe 中，用户程序随后继续执行，这就是 ecall 和 sret 共同形成的完整闭环。
这一部分的知识点也直接连接到后面的进程管理：fork 会走向进程复制，exec 会走向新程序加载，exit 会走向进程退出，wait 会走向僵尸回收。把这些接口放在同一条调用链里理解，能更清楚地看出用户进程生命周期是如何被内核组织起来的。

lab5/lab5_3_4_first_user.html.body:
第一次进入用户态
do_execve 和 load_icode 解决的是“把新程序装进当前进程地址空间”的问题，而 kernel_execve 解决的是“装好以后，怎样真正切回用户态执行”的问题。这两件事必须配合起来，系统才能第一次从内核态进入用户态。
do_execve 的核心职责是回收旧地址空间、建立新地址空间，并让当前进程的映像变成新的程序。它会清理旧的 mm，调用 load_icode 装入 ELF 程序，并更新进程名称和执行上下文。load_icode 则负责完成更细的工作：建立新的页表和用户栈，装入代码段与数据段，并把 trapframe 配置成一个可以从用户入口地址开始执行的状态。
但只做完这些还不够，因为内核此时仍然停留在 S 态。kernel_execve 的关键作用，就是把当前进程临时切换到一个适合 trap 返回的上下文，让 CPU 走通用的异常返回路径，最终通过 sret 进入 U 态。换句话说，do_execve 负责“准备好”，kernel_execve 负责“真正切过去”。
那么我们如何实现 kernel_execve() 函数？能否直接调用 do_execve()？
static int kernel_execve(const char *name, unsigned char *binary, size_t size) {
    int64_t ret = 0, len = strlen(name);
    ret = do_execve(name, len, binary, size);
    cprintf("ret = %d\n", ret);
    return ret;
}

这样做行不通。原因在于，do_execve() 只负责把新的程序映像和执行上下文准备好，却没有让 CPU 真正走到返回用户态的那条路径。如果内核里只是直接调用 do_execve()，执行流仍然会停留在 S 态，新的用户程序并不会自动开始跑起来。
系统中的用户态切换，依赖的是中断处理的返回路径，也就是最终要走到 sret。对于正常的用户态 exec() 调用，这一步会在系统调用返回时自动完成；但这里不一样，我们是在内核线程上下文里启动第一个用户程序，并没有现成的用户态异常返回可以借用。
目前我们在 S mode 下，所以不能通过 ecall 重新触发一次系统调用进入返回路径。一个取巧的办法是人造一次 ebreak 异常，再借助异常处理里的系统调用返回路径完成切换。不过这种做法比较绕，理解上也不够直接。
另一种更清晰的方法，是手动构造一个新的 trapframe，把它放到当前进程的内核栈顶，再主动跳转到 __trapret。这样就能直接复用中断返回路径：先恢复寄存器，再执行 sret，最终顺利从内核态切回用户态。这个思路才是 kernel_execve 的核心。
理解这条链路时，最重要的是 trapframe 里的三个信息：入口地址决定从哪里开始执行，用户栈顶决定用户程序的栈空间，sstatus 里的特权级位决定 sret 返回到什么模式。只要这三项都正确，第一个用户程序就能从镜像中的入口点开始运行。

lab6/lab6_3_3_schedule.html.body:
调度算法框架
调度算法框架实现为一个结构体，其中保存了各个函数指针。通过实现这些函数指针即可实现各个调度算法。结构体的定义如下：
struct sched_class {
    // 调度类的名字
    const char *name;
    // 初始化run queue
    void (*init)(struct run_queue *rq);
    // 把进程放进run queue，这个是run queue的维护函数
    void (*enqueue)(struct run_queue *rq, struct proc_struct *proc);
    // 把进程取出run queue
    void (*dequeue)(struct run_queue *rq, struct proc_struct *proc);
    // 选择下一个要执行的进程
    struct proc_struct *(*pick_next)(struct run_queue *rq);
    // 每次时钟中断调用
    void (*proc_tick)(struct run_queue *rq, struct proc_struct *proc);
};

所有的进程被组织成一个run_queue数据结构。这个数据结构虽然没有保存在调度类中，但是是由调度类来管理的。目前ucore仅支持单个CPU核心，所以只有一个全局的run_queue。
我们在进程控制块中也记录了一些和调度有关的信息：
struct proc_struct {
    // ...
    // 表示这个进程是否需要调度
    volatile bool need_resched;
    // run queue的指针
    struct run_queue *rq;
    // 与这个进程相关的run queue表项
    list_entry_t run_link;
    // 这个进程剩下的时间片
    int time_slice;
    // 以下几个都和Stride调度算法实现有关
    // 这个进程在优先队列中对应的项
    skew_heap_entry_t lab6_run_pool;
    // 该进程的Stride值
    uint32_t lab6_stride;
    // 该进程的优先级
    uint32_t lab6_priority;
};

前面的几个成员变量的含义都比较直接，最后面的几个的含义可以参见Stride调度算法。这也是本次lab的实验内容。
结构体run_queue实现了运行队列，其内部结构如下：
struct run_queue {
    // 保存着链表头指针
    list_entry_t run_list;
    // 运行队列中的线程数
    unsigned int proc_num;
    // 最大的时间片大小
    int max_time_slice;
    // Stride调度算法中的优先队列
    skew_heap_entry_t *lab6_run_pool;
};

有了这些基础，我们就来实现一个最简单的调度算法：Round-Robin调度算法，也叫时间片轮转调度算法。

lab7/lab7_4_semaphore.html.body:
信号量
信号量（semaphore）是一种同步互斥的实现。semaphore一词来源于荷兰语，原来是指火车信号灯。想象一些火车要进站，火车站里有n个站台，那么同一时间只能有n辆火车进站装卸货物。当火车站里已经有了n辆火车，信号灯应该通知后面的火车不能进站了。当有火车出站之后，信号灯应该告诉后面的火车可以进站。
这个问题放在操作系统的语境下就是有一个共享资源只能支持n个线程并行的访问，信号量统计目前有多少进程正在访问，当同时访问的进程数小于n时就可以让新的线程进入，当同时访问的进程数为n时想要访问的进程就需要等待。
在信号量中，一般用两种操作来刻画申请资源和释放资源：P操作申请一份资源，如果申请不到则等待；V操作释放一份资源，如果此时有进程正在等待，则唤醒该进程。在ucore中，我们使用down函数实现P操作，up函数实现V操作。
首先是信号量结构体的定义：
typedef struct {
    int value;
    wait_queue_t wait_queue;
} semaphore_t;

其中的value表示信号量的值，其正值表示当前可用的资源数量，负值表示正在等待资源的进程数量。wait_queue即为这个信号量相对应的等待队列。
down函数实现的是P操作。首先关闭中断，然后判断信号量的值是否为正，如果是正值说明进程可以获得信号量，将信号量的值减一，打开中断然后函数返回即可。否则表示无法获取信号量，将自己的进程保存进等待队列，打开中断，调用schedule函数进行调度。等到V操作唤醒进程的时候，其会回到调用schedule函数后面，将自身从等待队列中删除（此过程需要关闭中断）并返回即可。具体的实现如下：
static __noinline uint32_t __down(semaphore_t *sem, uint32_t wait_state) {
    bool intr_flag;
    local_intr_save(intr_flag);
    if (sem->value > 0) {
        sem->value --;
        local_intr_restore(intr_flag);
        return 0;
    }
    wait_t __wait, *wait = &__wait;
    wait_current_set(&(sem->wait_queue), wait, wait_state);
    local_intr_restore(intr_flag);

    schedule();

    local_intr_save(intr_flag);
    wait_current_del(&(sem->wait_queue), wait);
    local_intr_restore(intr_flag);

    if (wait->wakeup_flags != wait_state) {
        return wait->wakeup_flags;
    }
    return 0;
}

up函数实现了V操作。首先关闭中断，如果释放的信号量没有进程正在等待，那么将信号量的值加一，打开中断直接返回即可。如果有进程正在等待，那么唤醒这个进程，把它放进就绪队列，打开中断并返回。具体的实现如下：
static __noinline void __up(semaphore_t *sem, uint32_t wait_state) {
    bool intr_flag;
    local_intr_save(intr_flag);
    {
        wait_t *wait;
        if ((wait = wait_queue_first(&(sem->wait_queue))) == NULL) {
            sem->value ++;
        }
        else {
            assert(wait->proc->wait_state == wait_state);
            wakeup_wait(&(sem->wait_queue), wait, wait_state, 1);
        }
    }
    local_intr_restore(intr_flag);
}

下一节，我们来看看如何使用信号量实现条件变量以及管程。

lab7/lab7_5_monitor.html.body:
管程
我们已经有了基本的同步互斥机制实现，下面让我们用这些机制来实现一个管程，从而解决哲学家就餐问题。
为什么要使用管程呢？引入管程相当于将底层的同步互斥机制封装了起来，对外提供已经经过同步的接口供进程使用，大大降低了并行进程开发的门槛。管程主要由四个部分组成：

管程内部的共享变量
管程内部的条件变量
管程内部并发执行的进程
对局部于管程内部的共享数据设置初始值的语句

由此可见，管程把需要互斥访问的变量直接包装了起来，对共享变量的访问只能通过管程提供的相应接口，方便了多进程的编写。但是管程只有同步互斥是不够的，可能需要条件变量。条件变量类似于信号量，只不过在信号量中进程等待某一个资源可用，而条件变量中进程等待条件变量相应的资源为真。条件变量的结构体如下：
typedef struct condvar{
    // 信号量
    semaphore_t sem;
    // 正在等待的线程数
    int count;
    // 自己属于哪一个管程
    monitor_t * owner;
} condvar_t;

我们主要需要实现两个函数，其中：
cond_wait表示当前线程暂时无法继续执行，需要等待某个条件成立。
调用该操作后，当前线程应当：不再继续占用管程执行权；进入相应条件变量的等待状态；等待其他线程通过 cond_signal 通知该条件可能已经满足；被唤醒后重新获得继续执行的机会。
cond_signal表示当前线程已经改变了某些共享状态，使得等待某个条件的线程可能可以继续执行。
调用该操作后，应当根据当前条件变量的等待情况，对相应等待线程进行唤醒。
注意：
本实验不直接给出 cond_wait() 和 cond_signal() 的具体实现算法。学生需要根据管程的数据结构、信号量接口以及上述行为要求完成实现。
管程的内部实现如下所示：
typedef struct monitor{
    // 保证管程互斥访问的信号量
    semaphore_t mutex;
    // 里面放着正在等待进入管程执行的进程
    semaphore_t next;
    // 正在等待进入管程的进程数
    int next_count;
    // 条件变量
    condvar_t *cv;
} monitor_t;

条件变量cv被设置时，会使得当前在管程内的进程等待条件变量而睡眠，其他进程进入管程执行。当cv被唤醒的时候，之前等待这个条件变量的进程也会被唤醒，进入管程执行。由于管程内部只能由一个条件变量，所以通过设置next来维护下一个要运行的进程是哪一个。
在理解管程和条件变量之后，可以进一步使用它们解决经典的哲学家就餐问题。本实验设置 5 名哲学家。每名哲学家在“思考”和“进餐”之间不断切换。哲学家进餐需要同时获得自己左右两侧的叉子，因此多个哲学家之间存在资源竞争。
实验中使用以下状态表示哲学家的当前状态：
#define THINKING 0
#define HUNGRY   1
#define EATING   2
同时，实验框架已经提供以下共享状态：
int state_condvar[N];
以及管程：
monitor_t mt;
monitor_t *mtp = &mt;
每个哲学家还对应一个用于等待的条件变量。
使用管程实现哲学家就餐时，程序需要满足以下行为要求。
要求一：哲学家进入进餐状态必须满足资源条件
哲学家只有在：

自己处于饥饿状态；
左侧哲学家没有进餐；
右侧哲学家没有进餐；

时，才允许进入 EATING 状态。
否则，当前哲学家不能获得进餐所需要的两个叉子，应当等待。
要求二：等待中的哲学家不能持续占用管程
如果当前哲学家无法进餐，需要通过条件变量进入等待状态。
等待期间，其他哲学家应该能够进入管程并修改共享状态。
因此，不能让一个因为条件不满足而等待的线程一直占用管程。
要求三：哲学家结束进餐后需要改变共享状态 
哲学家完成进餐后，需要从：
EATING
转换为：
THINKING
此时原来被该哲学家占用的资源重新变得可用。
其他处于 HUNGRY 状态的哲学家可能因此获得进餐机会。
要求四：状态变化后需要考虑等待线程
当某个哲学家的状态发生变化后，可能使相邻哲学家的进餐条件发生变化。
因此，实现中需要正确使用条件变量的通知机制，使满足条件的等待线程能够获得继续执行的机会。
要求五：不能破坏管程的互斥语义
对以下共享状态的修改必须在管程提供的同步机制下完成：
state_condvar[]
不能让多个哲学家线程同时无保护地修改共享状态。
具体的实现在sync/check_sync.c中完成

lab8/lab8_3_2_vfs.html.body:
文件系统抽象层VFS
文件系统抽象层是把不同文件系统的对外共性接口提取出来，形成一个函数指针数组，这样，通用文件系统访问接口层只需访问文件系统抽象层，而不需关心具体文件系统的实现细节和接口。
file & dir 接口
file & dir 接口层定义了进程在内核中直接访问的文件相关信息，这定义在 file 数据结构中，具体描述如下：
// kern/fs/file.h
struct file {
    enum {
        FD_NONE, FD_INIT, FD_OPENED, FD_CLOSED,
    } status;                         //访问文件的执行状态
    bool readable;                    //文件是否可读
    bool writable;                    //文件是否可写
    int fd;                           //文件在fd_array中的索引值
    off_t pos;                        //访问文件的当前位置
    struct inode *node;               //该文件对应的内存inode指针
    int open_count;                   //打开此文件的次数
};

而在 kern/process/proc.h 中的 proc_struct 结构中加入了描述了进程访问文件的数据接口 files_struct，其数据结构定义如下：
// kern/fs/fs.h
struct files_struct {
    struct inode *pwd;                //进程当前执行目录的内存inode指针
    struct file *fd_array;            //进程打开文件的数组
    int files_count;                  //访问此文件的线程个数
    semaphore_t files_sem;            //确保对进程控制块中files_struct的互斥访问
};

当创建一个进程后，该进程的 files_struct 将会被初始化或复制父进程的 files_struct。当用户进程打开一个文件时，将从 fd_array 数组中取得一个空闲 file 项，然后会把此 file 的成员变量 node 指针指向一个代表此文件的 inode 的起始地址。
inode 接口
index node 是位于内存的索引节点，它是 VFS 结构中的重要数据结构，因为它实际负责把不同文件系统的特定索引节点信息（甚至不能算是一个索引节点）统一封装起来，避免了进程直接访问具体文件系统。其定义如下：
// kern/fs/vfs/inode.h
struct inode {
    union {                                 //包含不同文件系统特定inode信息的union成员变量
        struct device __device_info;          //设备文件系统内存inode信息
        struct sfs_inode __sfs_inode_info;    //SFS文件系统内存inode信息
    } in_info;
    enum {
        inode_type_device_info = 0x1234,
        inode_type_sfs_inode_info,
    } in_type;                          //此inode所属文件系统类型
    int ref_count;                      //此inode的引用计数
    int open_count;                     //打开此inode对应文件的个数
    struct fs *in_fs;                   //抽象的文件系统，包含访问文件系统的函数指针
    const struct inode_ops *in_ops;     //抽象的inode操作，包含访问inode的函数指针
};

在 inode 中，有一成员变量为 in_ops，这是对此 inode 的操作函数指针列表，其数据结构定义如下：
struct inode_ops {
    unsigned long vop_magic;
    int (*vop_open)(struct inode *node, uint32_t open_flags);
    int (*vop_close)(struct inode *node);
    int (*vop_read)(struct inode *node, struct iobuf *iob);
    int (*vop_write)(struct inode *node, struct iobuf *iob);
    int (*vop_getdirentry)(struct inode *node, struct iobuf *iob);
    int (*vop_create)(struct inode *node, const char *name, bool excl, struct inode **node_store);
    int (*vop_lookup)(struct inode *node, char *path, struct inode **node_store);
……
 };

参照上面对 SFS 中的索引节点操作函数的说明，可以看出 inode_ops 是对常规文件、目录、设备文件所有操作的一个抽象函数表示。对于某一具体的文件系统中的文件或目录，只需实现相关的函数，就可以被用户进程访问具体的文件了，且用户进程无需了解具体文件系统的实现细节。

lab8/lab8_3_4_device.html.body:
设备
在本实验中，为了统一地访问设备(device)，我们可以把一个设备看成一个文件，通过访问文件的接口来访问设备。目前实现了 stdin 设备文件文件、stdout 设备文件、disk0 设备。stdin 设备就是键盘，stdout 设备就是控制台终端的文本显示，而 disk0 设备是承载 SFS 文件系统的磁盘设备。下面看看 ucore 是如何让用户把设备看成文件来访问。
设备的定义
为了表示一个设备，需要有对应的数据结构，ucore 为此定义了 struct device，如下：
可以认为struct device是一个比较抽象的“设备”的定义。一个具体设备，只要实现了d_open()打开设备， d_close()关闭设备，d_io()(读写该设备，write参数是true/false决定是读还是写)，d_ioctl()(input/output control)四个函数接口，就可以被文件系统使用了。
// kern/fs/devs/dev.h
/*
 * Filesystem-namespace-accessible device.
 * d_io is for both reads and writes; the iobuf will indicates the direction.
 */
struct device {
    size_t d_blocks;
    size_t d_blocksize;
    int (*d_open)(struct device *dev, uint32_t open_flags);
    int (*d_close)(struct device *dev);
    int (*d_io)(struct device *dev, struct iobuf *iob, bool write);
    int (*d_ioctl)(struct device *dev, int op, void *data);
};

#define dop_open(dev, open_flags)           ((dev)->d_open(dev, open_flags))
#define dop_close(dev)                      ((dev)->d_close(dev))
#define dop_io(dev, iob, write)             ((dev)->d_io(dev, iob, write))
#define dop_ioctl(dev, op, data)            ((dev)->d_ioctl(dev, op, data))

这个数据结构能够支持对块设备（比如磁盘）、字符设备（比如键盘）的表示，完成对设备的基本操作。
但这个设备描述没有与文件系统以及表示一个文件的 inode 数据结构建立关系，为此，还需要另外一个数据结构把 device 和 inode 联通起来，这就是 vfs_dev_t 数据结构。
利用 vfs_dev_t 数据结构，就可以让文件系统通过一个链接 vfs_dev_t 结构的双向链表找到 device 对应的 inode 数据结构，一个 inode 节点的成员变量 in_type 的值是 0x1234，则此 inode 的成员变量 in_info 将成为一个 device 结构。这样 inode 就和一个设备建立了联系，这个 inode 就是一个设备文件。
// kern/fs/vfs/vfsdev.c
// device info entry in vdev_list 
typedef struct {
    const char *devname;
    struct inode *devnode;
    struct fs *fs;
    bool mountable;
    list_entry_t vdev_link;
} vfs_dev_t;
#define le2vdev(le, member)                         \
    to_struct((le), vfs_dev_t, member) //为了使用链表定义的宏, 做到现在应该对它很熟悉了

static list_entry_t vdev_list;     // device info list in vfs layer
static semaphore_t vdev_list_sem; // 互斥访问的semaphore
static void lock_vdev_list(void) {
    down(&vdev_list_sem);
}
static void unlock_vdev_list(void) {
    up(&vdev_list_sem);
}

ucore 虚拟文件系统为了把这些设备链接在一起，还定义了一个设备链表，即双向链表 vdev_list，这样通过访问此链表，可以找到 ucore 能够访问的所有设备文件。
注意这里的vdev_list对应一个vdev_list_sem。在文件系统中，互斥访问非常重要，所以我们将看到很多的semaphore。
我们使用iobuf结构体传递一个IO请求（要写入设备的数据当前所在内存的位置和长度/从设备读取的数据需要存储到的位置）
struct iobuf {
    void *io_base;     // the base addr of buffer (used for Rd/Wr)
    off_t io_offset;   // current Rd/Wr position in buffer, will have been incremented by the amount transferred
    size_t io_len;     // the length of buffer  (used for Rd/Wr)
    size_t io_resid;   // current resident length need to Rd/Wr, will have been decremented by the amount transferred.
};

注意设备文件的inode也有一个inode_ops成员, 提供设备文件应具备的接口。
